require('dotenv').config()
const mongoose = require('mongoose')

const url = process.env.MONGODB_URI
// I opted to use a local mongodb server served by a docker container instead of a cloud server
// I also added a testId field to make it easier to test the api without having to repeating GET requests to get the autogenerated IDs
console.log('connecting to db')

mongoose.connect(url, { family: 4})
  .then(() => {
    console.log('connected to db')
  }).catch(error => {
    console.log('error connecting to db:', error.message)
  })

const personSchema = new mongoose.Schema({
  name: {
    type: String,
    minLength: 3,
    required: true
  },
  number: {
    type: String,
    validate: {
      validator: (v) => {
        return /\d{2,3}-\d/.test(v) // regex was generated by ai 
      },
      message: props => `${props.value} is not a valid phone number!`
    },
    required: true
  },
  testId: Number
})

personSchema.set('toJson', {
  transform: (document, returnedObject) => {
    returnedObject.id = returnedObject._id.toString()
    delete returnedObject._id
    delete returnedObject.__v
  }
})

module.exports = mongoose.model('Person', personSchema)
